import{ledgers,decayRate,milkData,mean,milkPH,suitability,scenarios}from './eco3-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(x,y,s,n=17,c='#f8f4ed')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const path=(d,c='#b7cac5',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const dot=(x,y,r=5,c='#efaa90')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,h,c='#304e5e')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" fill="${c}" stroke="#a6beb8"/>`;
export const eco3SVG=(a,label)=>`<svg viewBox="0 0 560 440" role="img" aria-label="${esc(label)}">${a}</svg>`;
const positions={air:[135,110],plants:[425,110],animals:[425,290],dead:[135,290],sea:[135,290],vapour:[135,110],cloud:[425,110],land:[425,290]};
export function ledgerFigure({ledger='carbon',counts,progress,moving=false}={}){let l=ledgers[ledger],keys=Object.keys(l.initial),moves=Object.values(l.moves),idx=Math.min(moves.length-1,Math.floor((progress??0)*moves.length)),phase=(progress??0)*moves.length-idx,active=moves[idx],state=counts||l.initial,a=text(280,28,ledger==='carbon'?'Carbon: follow the same material':'Water: one material, different stores',22);for(let m of moves){let[x,y]=positions[m[0]],[u,v]=positions[m[1]],dx=u-x,dy=v-y,len=Math.hypot(dx,dy),sx=x+dx/len*62,sy=y+dy/len*48,ex=u-dx/len*62,ey=v-dy/len*48;let angle=Math.atan2(dy,dx),ax=ex-10*Math.cos(angle-.6),ay=ey-10*Math.sin(angle-.6),bx=ex-10*Math.cos(angle+.6),by=ey-10*Math.sin(angle+.6);a+=path(`M${sx} ${sy}L${ex} ${ey}M${ax} ${ay}L${ex} ${ey}L${bx} ${by}`,moving&&m===active?'#f5b598':'#91b2b460',2);}
for(let k of keys){let[x,y]=positions[k];a+=box(x-78,y-42,156,86)+text(x,y-12,l.labels[k],15)+text(x,y+14,state[k]+' units',17);for(let j=0;j<state[k];j++)a+=dot(x-40+j%7*13,y+29,3,'#d1d7b9');}if(moving){let[x,y]=positions[active[0]],[u,v]=positions[active[1]];a+=dot(x+(u-x)*phase,y+(v-y)*phase,9)+text(280,217,active[2],17,'#ffd2b6');}a+=text(280,380,`Closed account: ${l.total} material units`,18)+text(280,410,moving?'Moving marker traces a route; box totals are the starting example':'Use the controls to transfer one material unit',13)+text(280,432,'Selected stores only · arrows are not measured travel times',13);return eco3SVG(a,`${ledger} stores: `+keys.map(k=>l.labels[k]+' '+state[k]).join('; ')+(moving?'. Highlighted process: '+active[2]:'')+'. Closed total '+l.total+'. Material, not an energy-recycling account.');}
export function compostFigure({temp=25,moisture='moist',oxygen='air',revealed=true,progress=1}={}){let rate=decayRate(temp,moisture,oxygen),days=10*Math.max(0,Math.min(1,progress)),lost=rate*days,remaining=100-lost,a=text(280,28,'Microorganisms break down organic material',21)+box(75,95,225,260,'#263f45');for(let i=0;i<30;i++){let x=95+i%6*35,y=330-Math.floor(i/6)*40;if(!revealed||i<Math.round(remaining/100*30))a+=`<ellipse cx="${x}" cy="${y}" rx="13" ry="7" fill="${i%2?'#bba184':'#9aad8c'}"/>`;}a+=text(405,110,temp+'°C',24)+text(405,150,moisture==='moist'?'Moist':'Dry',18)+text(405,187,oxygen==='air'?'Oxygen available':'Limited oxygen',16);if(revealed)a+=text(405,245,remaining.toFixed(0)+' g left',22)+text(405,282,lost.toFixed(0)+' g lost',19)+text(405,321,days.toFixed(1)+' model days',16);else a+=text(405,260,'Predict first',20);a+=text(280,382,'Start 100 g · compare one condition at a time',17)+text(280,410,'Mass leaves this weighed material; matter is not destroyed',14)+text(280,432,'Original illustrative rates · not universal compost behaviour',13);return eco3SVG(a,`Fictional decomposition model, ${temp}°C, ${moisture}, oxygen ${oxygen}. `+(revealed?`${days} days, ${lost} g lost from initial 100 g; ${remaining} g remains.`:'Predict before revealing results.')+' Not a real measured rate.');}
export function biogasFigure(p=0){let phase=Math.min(3,Math.floor(p*4)),a=text(280,30,'Anaerobic breakdown can supply methane',22)+box(170,100,220,235,'#3a555c')+path('M280 100V70H465V160','#bdd0ce',8)+box(415,165,95,115)+text(462,207,'Collected',14)+text(462,235,'biogas',17)+text(280,150,'Oxygen excluded',17)+text(280,302,'Organic material',17);for(let i=0;i<8;i++)a+=dot(200+i%4*48,265-Math.floor(i/4)*25,8,'#c4b398');let q=(p*2)%1;a+=dot(280,240-q*150,6,'#c4dce2')+text(280,375,['Organic feed enters the digester','Microorganisms process material anaerobically','Methane-containing biogas is collected','Methane can be used as a fuel'][phase],17)+text(280,415,'Symbolic pathway · mixed biogas, not pure methane',14)+text(280,436,'Not a construction guide or a measured gas yield',13);return eco3SVG(a,'Anaerobic digester: organic material is broken down by microorganisms without oxygen; methane-containing biogas is collected for use as fuel. Symbolic gas path, no yield prediction.');}
export function milkFigure({temp=20,elapsed=0}={}){let ph=milkPH(temp,elapsed),ratio=Math.min(1,elapsed/mean(milkData[temp])),color=ratio>=1?'#e1cb78':'#b59bc0',a=text(280,28,'Lipase: follow a common pH endpoint',22)+box(75,90,240,260,'#40667b')+text(195,325,temp+'°C water bath',18)+`<path d="M150 120V270q45 35 90 0V120" fill="none" stroke="#d4e0dc" stroke-width="4"/><path d="M155 180V265q40 29 80 0V180Z" fill="${color}"/>`+text(420,133,elapsed+' s',28)+text(420,182,'pH '+ph.toFixed(2),24)+text(420,230,'Endpoint: 7.2',17)+text(420,275,ratio>=1?'Endpoint reached':'Time still running',16)+text(280,380,'Lipase releases fatty acids → pH falls',18)+text(280,410,'Natural milk decay involves lactic acid; this is a model',14)+text(280,432,'Original timings · indicative colour · no cell count',13);return eco3SVG(a,`Accelerated lipase model at ${temp}°C: ${elapsed} s, pH ${ph.toFixed(2)}, common endpoint 7.2. Fatty acids lower pH; natural milk decay involves lactic acid. Symbolic colour and original timings, not measured bacterial growth.`);}
export function milkGraph({points=[200,100,260],max=300}={}){max=Number.isFinite(max)&&max>0?max:300;let a=text(280,28,'Temperature and mean endpoint time',22)+path('M80 80V330H510'),out=false,pts=[];for(let i=0;i<4;i++)a+=text(48,335-i*250/3,(max*i/3).toFixed(0),14)+path(`M80 ${330-i*250/3}H510`,'#ffffff20',1);for(let[i,t]of[20,35,50].entries()){let x=110+i*180,v=points[i];a+=text(x,355,t,16);if(v!==''&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=max){let y=330-Number(v)/max*250;pts.push([x,y]);a+=dot(x,y,7)+text(x,y-13,v+' s',14);}else{pts.push(null);if(v!==''&&v!==undefined)out=true;}}for(let i=0;i<2;i++)if(pts[i]&&pts[i+1])a+=path(`M${pts[i][0]} ${pts[i][1]}L${pts[i+1][0]} ${pts[i+1][1]}`,'#edb598',2);if(out)a+=text(280,60,'Some points are outside this scale',15,'#ffd2b6');a+=text(280,390,'Horizontal: temperature / °C',17)+text(280,414,'Vertical: mean endpoint time / s',16)+text(280,435,'Original data · shortest time gives greatest 1/time',13);return eco3SVG(a,'Original lipase endpoint graph; temperatures 20,35,50°C. Times '+points.join(',')+' s; vertical maximum '+max+' s. '+(out?'Out-of-scale points omitted. ':'')+'Not a universal optimum or a direct microorganism count.');}
export function distributionFigure({scenario='baseline',revealed=true}={}){let sites=suitability(scenario),a=text(280,28,'Test every limit at each model site',22)+text(280,62,scenarios[scenario].label,18);for(let[i,s]of sites.entries()){let x=30+i*135;a+=box(x,100,120,225,revealed?(s.suitable?'#47665e':'#594f55'):'#304e5e')+text(x+60,130,'Site '+(i+1),18)+text(x+60,174,s.temp+'°C',18)+text(x+60,207,'Water '+s.water,15)+text(x+60,239,'CO₂ '+s.gas,15)+text(x+60,295,revealed?(s.suitable?'Meets limits':'Outside limits'):'Predict',14);}a+=text(280,362,'Limits: 10–20°C · water ≥4 · CO₂ index ≥300',16)+text(280,394,revealed?sites.filter(s=>s.suitable).length+' / 4 model sites meet every limit':'Predict the number of suitable sites',18)+text(280,422,'Fictional indices · suitability is not measured abundance',13)+text(280,439,'Local hypothetical gas scenario · not a global atmospheric forecast',12);return eco3SVG(a,'Fictional distribution scenario '+scenario+'. '+sites.map((s,i)=>`Site ${i+1}: ${s.temp}°C, water index ${s.water}, CO2 supply index ${s.gas}`+(revealed?`, ${s.suitable?'meets':'outside'} limits`:'')).join('; ')+'. Thresholds are illustrative, not actual species tolerances or global extinction evidence.');}
const evidence={
'carbon-evidence':['Photosynthesis: CO₂ carbon → plant biomass','Respiration: organic carbon → atmospheric CO₂','Decomposition also returns mineral ions to soil'],
'water-evidence':['Evaporation: liquid → gas','Condensation: gas → liquid cloud droplets','Plants return water vapour by transpiration'],
'decay-evidence':['Compost can return useful materials to soil','Anaerobic digestion can produce methane fuel','Temperature, moisture and oxygen affect decay'],
'decay-data':['Fresh example: 24 g lost in 6 days','Mean mass-loss rate = 24 ÷ 6 = 4 g/day','A mean rate belongs to its stated interval'],
'milk-method':['Change temperature; control relevant quantities','Equilibrate; repeat using one defined pH endpoint','Lipase model ≠ natural microbial milk decay'],
'distribution-evidence':['Seasonal, geographical and human-caused changes','Evaluate temperature, water and atmospheric gases','Actual presence also depends on other influences']};
export function eco3Figure(o={}){if(o.concealed)return eco3SVG(text(280,220,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');if(['carbon-ledger','carbon-process'].includes(o.kind))return ledgerFigure({...o,ledger:'carbon',moving:o.kind.endsWith('process')});if(['water-ledger','water-process'].includes(o.kind))return ledgerFigure({...o,ledger:'water',moving:o.kind.endsWith('process')});if(['compost-data','decay-process'].includes(o.kind))return compostFigure(o);if(o.kind==='biogas-process')return biogasFigure(o.progress??0);if(['milk-data','milk-process'].includes(o.kind))return milkFigure(o);if(o.kind==='milk-graph')return milkGraph(o);if(o.kind==='distribution-data')return distributionFigure(o);let rows=evidence[o.kind]||evidence['carbon-evidence'];return eco3SVG(text(280,40,'Connect process and evidence',22)+rows.map((s,i)=>text(280,140+i*90,s,16)).join('')+text(280,430,'Original educational comparison · use the stated context',13),rows.join('. '));}
